CREATE OR REPLACE FUNCTION public.set_project_file_upload_state(p_file_id uuid, p_attempt_id uuid, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  target_project_id uuid;
  changed boolean;
  target public.project_files;
BEGIN
  IF p_file_id IS NULL
    OR p_attempt_id IS NULL
    OR p_status IS NULL
    OR p_status NOT IN ('pending', 'ready', 'upload_failed', 'cleanup_failed')
  THEN
    RAISE EXCEPTION
      USING ERRCODE = '22023', MESSAGE = 'invalid_project_file_upload_state';
  END IF;

  target_project_id := public.lock_project_for_file_operation(p_file_id);
  IF target_project_id IS NULL THEN
    RETURN false;
  END IF;

  IF p_status = 'ready' THEN
    SELECT * INTO target FROM public.project_files WHERE id=p_file_id
      AND project_id=target_project_id AND upload_attempt_id=p_attempt_id
      AND status='pending' AND upload_lease_until > now() FOR UPDATE;
    IF NOT FOUND OR NOT public.settle_account_storage_artifact(p_attempt_id,target.storage_owner_id,target.uploaded_by,'project-files',target.storage_path) THEN
      RETURN false;
    END IF;
  END IF;

  UPDATE public.project_files
  SET status = p_status,
      upload_lease_until = CASE
        WHEN p_status = 'pending' THEN now() + interval '2 minutes'
        ELSE NULL
      END,
      updated_at = now()
  WHERE id = p_file_id
    AND project_id = target_project_id
    AND upload_attempt_id = p_attempt_id
  RETURNING true INTO changed;

  RETURN coalesce(changed, false);
END
$function$

